import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"存储与上下文架构","description":"Hearth 的 SQLite、内容 blob、执行器目录、统一模型注册表和上下文交接边界。","frontmatter":{"title":"存储与上下文架构","description":"Hearth 的 SQLite、内容 blob、执行器目录、统一模型注册表和上下文交接边界。","outline":[2]},"headers":[],"relativePath":"design/storage.md","filePath":"design/storage.md","lastUpdated":1794078214000}'),a={name:"design/storage.md"};function s(r,e,n,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="存储与上下文架构" tabindex="-1">存储与上下文架构 <a class="header-anchor" href="#存储与上下文架构" aria-label="Permalink to &quot;存储与上下文架构&quot;">​</a></h1><p class="lead">Hearth 把可重建的事实、正文内容和工作目录分开保存。SQLite 是唯一的状态索引与事件账本，文件系统只保存大体量正文、工作区和安装产物。上下文、模型绑定和执行器交接都从同一套记录恢复。</p><h2 id="核心约束" tabindex="-1">核心约束 <a class="header-anchor" href="#核心约束" aria-label="Permalink to &quot;核心约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>约束</th><th>含义</th></tr></thead><tbody><tr><td>单一写权威</td><td>服务端单进程写入 SQLite；界面、通知和统计只读取投影，不另建事实源</td></tr><tr><td>先记录再展示</td><td>任务、运行、上下文、模型绑定和迁移结果先落库，再通过 SSE 推送到前端</td></tr><tr><td>正文与索引分离</td><td>数据库保存元数据、摘要、哈希和引用；大文本进入内容 blob，工作产物留在任务工作区</td></tr><tr><td>每次执行可追溯</td><td>上下文条目带 <code>task_id</code>、<code>run_id</code>、<code>executor_id</code>、<code>provenance_json</code> 和稳定的 <code>executor_event_id</code></td></tr><tr><td>执行器不持有长期凭据</td><td>模型密钥经 AES-256-GCM 加密后存入数据库；执行器只在单次运行中获得解密后的配置</td></tr></tbody></table><p>当前数据库 schema 版本为 <strong>11</strong>。启动时由 <code>packages/eventlog/src/database.ts</code> 顺序执行建表与增量迁移，并写入 <code>PRAGMA user_version</code> 和 <code>app_meta.schemaVersion</code>。</p><h2 id="hearth-目录" tabindex="-1"><code>.hearth</code> 目录 <a class="header-anchor" href="#hearth-目录" aria-label="Permalink to &quot;\`.hearth\` 目录&quot;">​</a></h2><p>默认数据目录是仓库根目录下的 <code>.hearth/</code>，可用 <code>HEARTH_DATA_DIR</code> 覆盖。</p><table tabindex="0"><thead><tr><th>路径</th><th>保存什么</th><th>是否进入数据库备份</th></tr></thead><tbody><tr><td><code>.hearth/hearth.sqlite</code></td><td>事件、任务、运行、审批、效果、上下文索引、模型档案、设置和迁移记录</td><td>是</td></tr><tr><td><code>.hearth/master.key</code></td><td>本机加密主密钥，用于模型 API Key 等敏感字段</td><td>是，随备份口令二次加密</td></tr><tr><td><code>.hearth/context/blobs/</code></td><td>超过内联阈值的上下文正文，以内容 SHA-256 命名</td><td>否</td></tr><tr><td><code>.hearth/workspaces/tasks/&lt;taskId&gt;/</code></td><td>单个任务的工作区、输入、输出和 <code>.hearth</code> 检查点</td><td>否</td></tr><tr><td><code>.hearth/artifacts/</code></td><td>受管交付产物及其清单</td><td>否</td></tr><tr><td><code>.hearth/sources/</code></td><td>抓取或导入的来源正文</td><td>否</td></tr><tr><td><code>.hearth/attachments/</code></td><td>聊天附件</td><td>否</td></tr><tr><td><code>.hearth/outbox/</code></td><td>本地发件箱草稿与回执文件</td><td>否</td></tr><tr><td><code>.hearth/executors/codex/</code></td><td>由统一模型绑定生成的 Codex <code>config.toml</code> 与运行目录</td><td>否</td></tr><tr><td><code>.hearth/executors/deepseek-harness/</code></td><td>DeepSeek Harness 的 Provider 补丁和会话运行目录</td><td>否</td></tr><tr><td><code>.hearth/executors/&lt;id&gt;/</code></td><td>其他外部执行器的托管安装与运行目录</td><td>否</td></tr><tr><td><code>.hearth/backups/</code></td><td>AES-256-GCM 加密的数据库备份归档</td><td>—</td></tr><tr><td><code>.hearth/backups/legacy-dev/</code></td><td>首次迁移旧 JSON 设置时保留的原始副本</td><td>—</td></tr><tr><td><code>.hearth/device-frames/</code></td><td>桌面观察帧缓存</td><td>否</td></tr><tr><td><code>.hearth/git-cache/</code></td><td>仓库准备缓存</td><td>否</td></tr></tbody></table><p><code>model-settings.json</code> 和 <code>executor-settings.json</code> 只作为旧版本迁移来源保留，不再由设置页写入。迁移成功后不主动删除原文件，便于审计和回滚。</p><h2 id="sqlite-数据域" tabindex="-1">SQLite 数据域 <a class="header-anchor" href="#sqlite-数据域" aria-label="Permalink to &quot;SQLite 数据域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据域</th><th>主要表</th><th>作用</th></tr></thead><tbody><tr><td>事件账本</td><td><code>events</code></td><td>只追加的事实流，驱动 SSE、同步和投影重建</td></tr><tr><td>任务与运行</td><td><code>tasks</code>、<code>runs</code>、<code>run_checkpoints</code>、<code>task_proposals</code></td><td>任务状态机、执行尝试、预算与恢复点</td></tr><tr><td>对话</td><td><code>conversations</code>、<code>chat_messages</code></td><td>聊天消息和可 upsert 的 <code>task_status</code> 状态卡片</td></tr><tr><td>审批与副作用</td><td><code>approvals</code>、<code>effects</code>、<code>outbox_drafts</code></td><td>一次性授权、幂等执行和外部回执</td></tr><tr><td>产物与来源</td><td><code>artifacts</code>、<code>sources</code>、<code>source_items</code></td><td>交付物索引、来源正文索引和抓取记录</td></tr><tr><td>上下文</td><td><code>context_items</code>、<code>task_context_state</code>、<code>context_settings</code>、<code>handoffs</code></td><td>执行轨迹、任务摘要、上下文策略和交接记录</td></tr><tr><td>模型管理</td><td><code>model_profiles</code>、<code>executor_model_bindings</code>、<code>app_settings</code></td><td>统一模型档案、执行器绑定和聊天模型选择</td></tr><tr><td>设置迁移</td><td><code>settings_migrations</code></td><td>旧 JSON 导入的来源、备份路径、状态和错误</td></tr><tr><td>记忆与方法</td><td><code>memories</code>、<code>memory_*</code>、<code>method_*</code>、<code>method_applications</code></td><td>可纠正记忆、召回审计、方法演进和逐次注入证据</td></tr><tr><td>多设备与安全</td><td><code>devices</code>、<code>pairing_requests</code>、<code>sync_*</code>、<code>task_leases</code>、<code>security_*</code></td><td>配对、同步、租约、撤销与设备围栏</td></tr><tr><td>运维</td><td><code>maintenance_runs</code>、<code>backup_records</code>、<code>scheduled_jobs</code></td><td>维护任务、备份记录和周期作业</td></tr></tbody></table><p>方法应用记录是 append-only 的本地审计，不参与事件重放和跨设备同步。<code>tasks.method_id/method_version</code> 钉住显式绑定，<code>method_applications</code> 记录每次运行实际注入的方法版本、选择方式和提示词哈希；<code>method_candidates.generation</code> 表示采用代数，<code>fingerprint</code> 用于确定性候选去重。</p><h2 id="统一模型注册表" tabindex="-1">统一模型注册表 <a class="header-anchor" href="#统一模型注册表" aria-label="Permalink to &quot;统一模型注册表&quot;">​</a></h2><p>模型不再绑定在某个执行器的私有 JSON 文件里，而是拆成两层：</p><ol><li><strong>模型档案 <code>model_profiles</code></strong>：保存显示名、Provider、协议、Base URL、模型名和加密后的 API Key。</li><li><strong>执行器绑定 <code>executor_model_bindings</code></strong>：为每个执行器选择档案，并允许受约束的协议或模型覆盖。</li></ol><p><code>app_settings.model.chatProfileId</code> 记录 Hearth 当前聊天模型。它用于聊天、失败原因诊断和原生执行器；外部执行器只有在其绑定有效时才使用自己的模型档案。</p><p>协议兼容由服务端强制校验：</p><table tabindex="0"><thead><tr><th>执行器</th><th>允许的协议</th></tr></thead><tbody><tr><td><code>native</code></td><td><code>openai-chat</code>、<code>openai-responses</code>、<code>anthropic-messages</code>、<code>gemini</code></td></tr><tr><td><code>codex</code></td><td>仅 <code>openai-responses</code></td></tr><tr><td><code>deepseek-harness</code></td><td><code>openai-chat</code>、<code>openai-responses</code>、<code>anthropic-messages</code></td></tr><tr><td><code>hermes</code>、<code>qoder</code>、<code>workbuddy</code>、<code>kimi</code></td><td><code>openai-chat</code>、<code>openai-responses</code>、<code>anthropic-messages</code></td></tr></tbody></table><p>Codex 的绑定会生成独立的 <code>.hearth/executors/codex/config.toml</code>，固定使用 <code>wire_api = &quot;responses&quot;</code>，并通过进程环境注入密钥。本地地址（<code>localhost</code>、<code>127.0.0.1</code>、私有网段和 <code>.local</code>）不允许进入统一模型管理，避免把本机模型误当成云端档案。</p><h2 id="上下文生命周期" tabindex="-1">上下文生命周期 <a class="header-anchor" href="#上下文生命周期" aria-label="Permalink to &quot;上下文生命周期&quot;">​</a></h2><p>上下文是所有执行器共用的任务级记录，不依附于某个 CLI 的私有会话。</p><ol><li><strong>采集</strong>：原生运行时、Codex、DeepSeek Harness 和外部 CLI 把消息、工具调用、工具结果、检查点和通知转成统一的 <code>ContextItem</code>。</li><li><strong>去重</strong>：<code>executor_event_id</code> 在同一运行内唯一，重复通知不会重复写入。</li><li><strong>内联或落 blob</strong>：正文超过 <code>maxInlineBytes</code> 时写入 <code>.hearth/context/blobs/&lt;sha256&gt;.txt</code>，数据库只保存 <code>content_ref</code>、<code>sha256</code> 和截断后的内联片段。</li><li><strong>摘要</strong>：条目增长到 <code>summarizeAfterTokens</code> 后刷新 <code>task_context_state</code>，保留目标、计划、已完成、失败、产物和未解决问题。</li><li><strong>投影</strong>：执行器启动或接管时，按 <code>projectionTokenBudget</code> 生成受预算约束的上下文投影，而不是把全部历史直接塞给 CLI。</li><li><strong>交接</strong>：<code>handoffs</code> 保存诊断、交接包、来源运行、目标运行和 <code>context_watermark_seq</code>；接管执行器从同一水位继续，避免旧结果覆盖新状态。</li><li><strong>删除</strong>：删除任务上下文时清理 <code>context_items</code>、<code>task_context_state</code> 和不再被引用的 blob；其他任务仍引用的内容不会误删。</li></ol><p>上下文模式支持 <code>off</code>、<code>shadow</code> 和 <code>on</code>。<code>shadow</code> 只记录不注入，适合先观察采集质量；<code>on</code> 才把投影用于执行和接管。默认最多接管 2 次、同一执行器最多重试 1 次、保留 30 天。</p><h2 id="启动迁移" tabindex="-1">启动迁移 <a class="header-anchor" href="#启动迁移" aria-label="Permalink to &quot;启动迁移&quot;">​</a></h2><p>服务启动时按以下顺序处理旧设置：</p><ol><li>读取 <code>.hearth/model-settings.json</code> 和 <code>.hearth/executor-settings.json</code>。</li><li>把原文件复制到 <code>.hearth/backups/legacy-dev/</code>，文件名带时间或迁移标识。</li><li>在事务中写入 <code>model_profiles</code>、<code>executor_model_bindings</code> 和 <code>app_settings</code>。</li><li>在 <code>settings_migrations</code> 记录 <code>legacy-model-settings-v1</code>、<code>legacy-executor-settings-v1</code> 的来源、备份、状态和错误。</li><li>任一步失败则回滚数据库写入，并保留备份和失败记录，服务不会带着半迁移状态启动。</li></ol><p>迁移是幂等的：已完成的迁移 ID 不会重复导入；相同 Provider、地址、模型和协议的档案会复用，而不是创建重复记录。</p><h2 id="备份与恢复边界" tabindex="-1">备份与恢复边界 <a class="header-anchor" href="#备份与恢复边界" aria-label="Permalink to &quot;备份与恢复边界&quot;">​</a></h2><p>数据库备份包含 SQLite 快照、schema 版本、各表计数和本机 <code>master.key</code>，整个载荷使用用户口令派生的 AES-256-GCM 密钥加密。恢复前校验 schema 不高于当前版本、载荷哈希一致、候选数据库 <code>PRAGMA integrity_check</code> 为 <code>ok</code>，通过后才替换现有数据库。</p><p>备份<strong>不包含</strong>上下文 blob、任务工作区、产物正文、来源正文、附件和发件箱文件。需要完整迁移时，应同时复制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.hearth/context/blobs/</span></span>
<span class="line"><span>.hearth/workspaces/</span></span>
<span class="line"><span>.hearth/artifacts/</span></span>
<span class="line"><span>.hearth/sources/</span></span>
<span class="line"><span>.hearth/attachments/</span></span>
<span class="line"><span>.hearth/outbox/</span></span></code></pre></div><h2 id="运维检查" tabindex="-1">运维检查 <a class="header-anchor" href="#运维检查" aria-label="Permalink to &quot;运维检查&quot;">​</a></h2><p>设置页的“数据”分区展示数据库路径、schema 版本、执行器目录、上下文 blob 目录、迁移记录和旧 JSON 来源。排查问题时优先检查：</p><ul><li><code>settings_migrations</code>：旧设置是否已成功导入，失败原因是什么。</li><li><code>model_profiles</code> 与 <code>executor_model_bindings</code>：执行器是否绑定了协议兼容且带密钥的档案。</li><li><code>context_items</code> 与 <code>task_context_state</code>：任务是否记录了执行轨迹、摘要水位是否推进。</li><li><code>handoffs</code>：失败接管的目标、诊断和上下文水位是否一致。</li><li><code>backup_records</code>：最近备份是否成功、恢复是否通过完整性检查。</li></ul><p>所有路径都以数据库记录为准；不要手工编辑 <code>model-settings.json</code> 或 <code>executor-settings.json</code> 来改变运行配置。</p>`,35)])])}const g=t(a,[["render",s]]);export{_ as __pageData,g as default};
